#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
const int MAXN = 100005;
const int LOGN = 18;

vector<int> adj[MAXN];
int depth_node[MAXN];
int up[MAXN][LOGN];
int tin[MAXN], tout[MAXN], timer_dfs = 0;

pair<int, int> seg[4 * MAXN];

void dfs(int u, int p, int d) {
    depth_node[u] = d;
    up[u][0] = p;
    for (int i = 1; i < LOGN; ++i) {
        up[u][i] = up[up[u][i - 1]][i - 1];
    }
    tin[u] = ++timer_dfs;
    for (int v : adj[u]) {
        dfs(v, u, d + 1);
    }
    tout[u] = timer_dfs;
}

int get_kth_ancestor(int u, int k) {
    for (int i = 0; i < LOGN; ++i) {
        if ((k >> i) & 1) {
            u = up[u][i];
        }
    }
    return u;
}

void build(int node, int l, int r) {
    seg[node] = {INF, 0};
    if (l == r) return;
    int mid = (l + r) / 2;
    build(2 * node, l, mid);
    build(2 * node + 1, mid + 1, r);
}

void update(int node, int l, int r, int ql, int qr, pair<int, int> val) {
    if (ql <= l && r <= qr) {
        seg[node] = min(seg[node], val);
        return;
    }
    int mid = (l + r) / 2;
    if (ql <= mid) update(2 * node, l, mid, ql, qr, val);
    if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr, val);
}

pair<int, int> query(int node, int l, int r, int p) {
    pair<int, int> res = seg[node];
    if (l == r) return res;
    int mid = (l + r) / 2;
    if (p <= mid) res = min(res, query(2 * node, l, mid, p));
    else res = min(res, query(2 * node + 1, mid + 1, r, p));
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    for (int i = 2; i <= n; ++i) {
        int p;
        cin >> p;
        adj[p].push_back(i);
    }

    dfs(1, 1, 0);
    build(1, 1, n);

    int q;
    cin >> q;
    while (q--) {
        int type;
        cin >> type;
        if (type == 1) {
            int v, k;
            cin >> v >> k;
            pair<int, int> best = query(1, 1, n, tin[v]);
            if (best.first < depth_node[v]) {
                int A = best.second;
                if (k == 1) {
                    cout << A << "\n";
                } else {
                    cout << get_kth_ancestor(A, k - 1) << "\n";
                }
            } else {
                cout << get_kth_ancestor(v, k) << "\n";
            }
        } else {
            int v;
            cin >> v;
            pair<int, int> best = query(1, 1, n, tin[v]);
            if (best.first >= depth_node[v]) {
                update(1, 1, n, tin[v], tout[v], {depth_node[v], v});
            }
        }
    }

    return 0;
}
